-- Query: Update_Situatie
-- Type: Update

UPDATE Situatie_buget SET Situatie_buget.Compensare = IIf(IIf([SID]>0,0,IIf([Plata]+[Plati]>0,IIf(([ValoareContract]-([Plata]+[Plati]))<0,0,[ValoareContract]-([Plata]+[Plati])),IIf([SIC]>[ValoareContract],[ValoareContract],[SIC])))>0,IIf([SIC]>0 And [SFD]>0,[SIC],IIf([SID]>0,0,IIf([Plata]+[Plati]>0,IIf(([ValoareContract]-([Plata]+[Plati]))<0,0,[ValoareContract]-([Plata]+[Plati])),IIf([SIC]>[ValoareContract],[ValoareContract],[SIC])))),IIf([SID]>0,0,IIf([Plata]+[Plati]>0,IIf(([ValoareContract]-([Plata]+[Plati]))<0,0,[ValoareContract]-([Plata]+[Plati])),IIf([SIC]>[ValoareContract],[ValoareContract],[SIC])))), Situatie_buget.Anticipat = IIf(([Plata]+[Plati]-[ValoareContract]-[SID])>0,[Plata]+[Plati]-[SID]-[ValoareContract],0), Situatie_buget.SFD = IIf(Nz([SoldInitial],0)+Nz([ValoareContract],0)-(Nz([Plata],0)+Nz([Plati],0)-Nz([Retur],0))>0,Nz([SoldInitial],0)+Nz([ValoareContract],0)-(Nz([Plata],0)+Nz([Plati],0)-Nz([Retur],0)),0), Situatie_buget.SFC = IIf(Nz([SoldInitial],0)+Nz([ValoareContract],0)-(Nz([Plata],0)+Nz([Plati],0)-Nz([Retur],0))<0,Abs(Nz([SoldInitial],0)+Nz([ValoareContract],0)-(Nz([Plata],0)+Nz([Plati],0)-Nz([Retur],0))),0);
